export const envelope = [38, 18, 38];

export default function build(api) {
  const [W, H, D] = api.size;
  const theme = api.theme;
  const seatY = 5;

  // Theme palettes with safe fallbacks
  const woodPlanks = theme.wood?.planks || "minecraft:mangrove_planks";
  const woodLog = theme.wood?.log || "minecraft:mangrove_log";
  const woodStripped = theme.wood?.stripped || "minecraft:stripped_mangrove_log";
  const woodStairs = theme.wood?.stairs || "minecraft:mangrove_stairs";
  const woodSlab = theme.wood?.slab || "minecraft:mangrove_slab";
  const woodFence = theme.wood?.fence || "minecraft:mangrove_fence";
  const woodTrapdoor = theme.wood?.trapdoor || "minecraft:mangrove_trapdoor";

  const roofStairs = theme.roof?.stairs || woodStairs;
  const roofSlab = theme.roof?.slab || woodSlab;
  const roofSolid = theme.roof?.solid || woodPlanks;

  const stonePrimary = theme.stone?.primary || "minecraft:stone_bricks";
  const groundPlinth = theme.ground?.plinth || stonePrimary;

  // Block state helper functions
  function stair(base, facing, half = "bottom", shape = "straight") {
    const clean = base.split("[")[0];
    return `${clean}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function slab(base, type = "bottom") {
    const clean = base.split("[")[0];
    return `${clean}[type=${type}]`;
  }

  function log(base, axis = "y") {
    const clean = base.split("[")[0];
    return `${clean}[axis=${axis}]`;
  }

  function trapdoor(base, facing = "north", half = "bottom", open = "false") {
    const clean = base.split("[")[0];
    return `${clean}[facing=${facing},half=${half},open=${open}]`;
  }

  // 3D Voxel buffer
  const world = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Array(D).fill(null))
  );

  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      world[x][y][z] = block;
    }
  }

  function get(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return world[x][y][z];
    }
    return null;
  }

  function fillBox(x1, y1, z1, x2, y2, z2, block) {
    const minX = Math.min(x1, x2), maxX = Math.max(x1, x2);
    const minY = Math.min(y1, y2), maxY = Math.max(y1, y2);
    const minZ = Math.min(z1, z2), maxZ = Math.max(z1, z2);
    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          set(x, y, z, block);
        }
      }
    }
  }

  // ==========================================
  // 1. FLOATING PLATFORMS & BOARDWALK NETWORKS
  // ==========================================

  // Central Market Plaza (Y = 5)
  fillBox(12, 5, 10, 26, 5, 26, woodPlanks);
  // Log border framing under the plaza (Y = 4)
  for (let x = 12; x <= 26; x++) {
    set(x, 4, 10, log(woodStripped, "x"));
    set(x, 4, 26, log(woodStripped, "x"));
  }
  for (let z = 10; z <= 26; z++) {
    set(12, 4, z, log(woodStripped, "z"));
    set(26, 4, z, log(woodStripped, "z"));
  }

  // North Landing Jetty / Entry Pier (X: 17..21, Z: 0..10)
  fillBox(17, 5, 0, 21, 5, 10, woodPlanks);
  for (let z = 0; z <= 10; z++) {
    set(17, 4, z, log(woodStripped, "z"));
    set(21, 4, z, log(woodStripped, "z"));
  }

  // South Mooring Pier (X: 17..21, Z: 26..30)
  fillBox(17, 5, 26, 21, 5, 30, woodPlanks);

  // West Boardwalk Branch (X: 6..12, Z: 17..19)
  fillBox(6, 5, 17, 12, 5, 19, woodPlanks);

  // East Boardwalk Branch (X: 26..32, Z: 17..19)
  fillBox(26, 5, 17, 32, 5, 19, woodPlanks);

  // North-West Produce Raft (X: 4..12, Z: 5..14)
  fillBox(4, 5, 5, 12, 5, 14, woodPlanks);
  fillBox(10, 5, 9, 13, 5, 11, woodPlanks); // Link to plaza
  for (let x = 4; x <= 12; x++) {
    set(x, 4, 5, log(woodStripped, "x"));
    set(x, 4, 14, log(woodStripped, "x"));
  }
  for (let z = 5; z <= 14; z++) {
    set(4, 4, z, log(woodStripped, "z"));
    set(12, 4, z, log(woodStripped, "z"));
  }

  // North-East Tea & Spice Raft (X: 26..34, Z: 5..14)
  fillBox(26, 5, 5, 34, 5, 14, woodPlanks);
  fillBox(25, 5, 9, 27, 5, 11, woodPlanks); // Link to plaza
  for (let x = 26; x <= 34; x++) {
    set(x, 4, 5, log(woodStripped, "x"));
    set(x, 4, 14, log(woodStripped, "x"));
  }
  for (let z = 5; z <= 14; z++) {
    set(26, 4, z, log(woodStripped, "z"));
    set(34, 4, z, log(woodStripped, "z"));
  }

  // South-West Artisan & Pottery Raft (X: 4..12, Z: 26..35)
  fillBox(4, 5, 26, 12, 5, 35, woodPlanks);
  fillBox(10, 5, 24, 13, 5, 26, woodPlanks); // Link to plaza
  for (let x = 4; x <= 12; x++) {
    set(x, 4, 26, log(woodStripped, "x"));
    set(x, 4, 35, log(woodStripped, "x"));
  }
  for (let z = 26; z <= 35; z++) {
    set(4, 4, z, log(woodStripped, "z"));
    set(12, 4, z, log(woodStripped, "z"));
  }

  // South-East Fisher's Raft (X: 25..35, Z: 26..35)
  fillBox(25, 5, 26, 35, 5, 35, woodPlanks);
  fillBox(24, 5, 24, 27, 5, 26, woodPlanks); // Link to plaza
  for (let x = 25; x <= 35; x++) {
    set(x, 4, 26, log(woodStripped, "x"));
    set(x, 4, 35, log(woodStripped, "x"));
  }
  for (let z = 26; z <= 35; z++) {
    set(25, 4, z, log(woodStripped, "z"));
    set(35, 4, z, log(woodStripped, "z"));
  }

  // ==========================================
  // 2. CENTRAL GRAND BAZAAR PAVILION
  // ==========================================
  // 8 Main Timber Stilt Pillars (X: 13, 19, 25; Z: 12, 18, 24)
  const pavilionPillars = [
    [13, 12], [19, 12], [25, 12],
    [13, 18],           [25, 18],
    [13, 24], [19, 24], [25, 24]
  ];
  for (const [px, pz] of pavilionPillars) {
    for (let y = 5; y <= 10; y++) {
      set(px, y, pz, log(woodLog, "y"));
    }
  }

  // Horizontal Tie Beams at Y = 9 and Y = 10
  for (const z of [12, 18, 24]) {
    for (let x = 13; x <= 25; x++) {
      set(x, 9, z, log(woodLog, "x"));
      set(x, 10, z, log(woodLog, "x"));
    }
  }
  for (const x of [13, 19, 25]) {
    for (let z = 12; z <= 24; z++) {
      set(x, 9, z, log(woodLog, "z"));
      set(x, 10, z, log(woodLog, "z"));
    }
  }

  // Lower Tier Roof Eaves (Y = 10) around the pavilion
  for (let x = 11; x <= 27; x++) {
    set(x, 10, 11, stair(roofStairs, "north"));
    set(x, 10, 25, stair(roofStairs, "south"));
  }
  for (let z = 11; z <= 25; z++) {
    set(11, 10, z, stair(roofStairs, "west"));
    set(27, 10, z, stair(roofStairs, "east"));
  }
  // Roof corners at Y = 10
  set(11, 10, 11, slab(roofSlab, "bottom"));
  set(27, 10, 11, slab(roofSlab, "bottom"));
  set(11, 10, 25, slab(roofSlab, "bottom"));
  set(27, 10, 25, slab(roofSlab, "bottom"));

  // Lower roof slope at Y = 11
  for (let x = 12; x <= 26; x++) {
    set(x, 11, 12, stair(roofStairs, "north"));
    set(x, 11, 24, stair(roofStairs, "south"));
  }
  for (let z = 12; z <= 24; z++) {
    set(12, 11, z, stair(roofStairs, "west"));
    set(26, 11, z, stair(roofStairs, "east"));
  }

  // Clerestory Posts & Upper Gable Roof (Y = 11..14)
  const clerestoryPosts = [[15, 14], [23, 14], [15, 22], [23, 22]];
  for (const [cx, cz] of clerestoryPosts) {
    for (let y = 11; y <= 13; y++) {
      set(cx, y, cz, log(woodLog, "y"));
    }
  }

  // Upper Roof Tier (Y = 12..14)
  for (let z = 13; z <= 23; z++) {
    // Y = 12 outer slope
    set(14, 12, z, stair(roofStairs, "west"));
    set(24, 12, z, stair(roofStairs, "east"));
    // Y = 13 inner slope
    set(16, 13, z, stair(roofStairs, "west"));
    set(22, 13, z, stair(roofStairs, "east"));
    // Y = 14 central ridge
    set(18, 14, z, roofSolid);
    set(19, 14, z, roofSolid);
    set(20, 14, z, roofSolid);
    set(19, 15, z, slab(roofSlab, "bottom"));
  }

  // Asian-style flared gable horn finials at ridge ends
  set(19, 15, 12, stair(roofStairs, "south", "top"));
  set(19, 16, 11, stair(roofStairs, "north"));
  set(19, 15, 24, stair(roofStairs, "north", "top"));
  set(19, 16, 25, stair(roofStairs, "south"));

  // Pavilion Interior Hanging Lanterns
  const lanternLocs = [[16, 15], [22, 15], [16, 21], [22, 21]];
  for (const [lx, lz] of lanternLocs) {
    set(lx, 9, lz, "minecraft:chain[axis=y]");
    set(lx, 8, lz, "minecraft:lantern[hanging=true]");
  }

  // ==========================================
  // 3. MOORED BOATS & SAMPANS
  // ==========================================

  function buildSampan(xMin, xMax, zMin, zMax, yBase, wool1, wool2, isNorthFacing) {
    const xMid = Math.floor((xMin + xMax) / 2);

    // Keel
    for (let z = zMin; z <= zMax; z++) {
      set(xMid, yBase, z, log(woodStripped, "z"));
    }

    // Hull Floor (Y = yBase)
    for (let x = xMin + 1; x <= xMax - 1; x++) {
      for (let z = zMin + 1; z <= zMax - 1; z++) {
        set(x, yBase, z, woodPlanks);
      }
    }

    // Gunwales (Y = yBase + 1)
    for (let z = zMin + 2; z <= zMax - 2; z++) {
      set(xMin, yBase + 1, z, stair(woodStairs, "east"));
      set(xMax, yBase + 1, z, stair(woodStairs, "west"));
    }

    // Tapered Prow and Stern
    const bowZ = isNorthFacing ? zMin : zMax;
    const sternZ = isNorthFacing ? zMax : zMin;

    // Bow
    set(xMid, yBase + 1, bowZ, slab(woodSlab, "top"));
    set(xMid - 1, yBase + 1, bowZ + (isNorthFacing ? 1 : -1), stair(woodStairs, isNorthFacing ? "south" : "north"));
    set(xMid, yBase + 1, bowZ + (isNorthFacing ? 1 : -1), stair(woodStairs, isNorthFacing ? "south" : "north"));
    set(xMid + 1, yBase + 1, bowZ + (isNorthFacing ? 1 : -1), stair(woodStairs, isNorthFacing ? "south" : "north"));

    // Stern & Rudder tiller
    set(xMid, yBase + 1, sternZ, woodPlanks);
    set(xMid, yBase + 2, sternZ, woodFence);
    set(xMid, yBase + 3, sternZ, woodFence);
    set(xMid, yBase + 3, sternZ + (isNorthFacing ? 1 : -1), woodFence);

    // Midship Canopy (Z: zMin + 4 to zMax - 4)
    const canZ1 = zMin + 4;
    const canZ2 = zMax - 4;

    // Canopy corner posts
    set(xMin, yBase + 2, canZ1, woodFence);
    set(xMax, yBase + 2, canZ1, woodFence);
    set(xMin, yBase + 2, canZ2, woodFence);
    set(xMax, yBase + 2, canZ2, woodFence);

    // Arched Canopy Roof
    for (let z = canZ1; z <= canZ2; z++) {
      const wool = (z % 2 === 0) ? wool1 : wool2;
      set(xMin, yBase + 3, z, slab(woodSlab, "top"));
      set(xMax, yBase + 3, z, slab(woodSlab, "top"));
      for (let x = xMin + 1; x <= xMax - 1; x++) {
        set(x, yBase + 4, z, wool);
      }
    }
  }

  // Sampan 1 (West Merchant Boat, X: 2..6, Z: 16..27)
  buildSampan(2, 6, 16, 27, 4, "minecraft:cyan_wool", "minecraft:white_wool", true);
  // Cargo in Sampan 1
  set(3, 5, 19, "minecraft:barrel[facing=up]");
  set(4, 5, 19, "minecraft:melon");
  set(5, 5, 19, "minecraft:barrel[facing=up]");
  set(3, 5, 20, "minecraft:terracotta");
  set(4, 5, 21, "minecraft:lantern[hanging=false]");
  // Mooring ropes to West Boardwalk
  set(6, 5, 18, woodFence);
  set(7, 5, 18, woodPlanks);
  set(6, 5, 23, woodFence);
  set(7, 5, 23, woodPlanks);

  // Sampan 2 (East Fish & Rice Boat, X: 31..35, Z: 16..27)
  buildSampan(31, 35, 16, 27, 4, "minecraft:red_wool", "minecraft:white_wool", true);
  // Cargo in Sampan 2
  set(32, 5, 19, "minecraft:barrel[facing=up]");
  set(33, 5, 19, "minecraft:hay_block[axis=y]");
  set(34, 5, 19, "minecraft:barrel[facing=up]");
  set(33, 5, 21, "minecraft:lantern[hanging=false]");
  set(32, 5, 22, "minecraft:barrel[facing=up]");
  // Mooring ropes to East Boardwalk
  set(31, 5, 18, woodFence);
  set(30, 5, 18, woodPlanks);
  set(31, 5, 23, woodFence);
  set(30, 5, 23, woodPlanks);

  // Sampan 3 (South Longtail Boat, X: 16..20, Z: 29..37)
  buildSampan(16, 20, 29, 37, 4, "minecraft:orange_wool", "minecraft:yellow_wool", false);
  // Longtail propeller shaft extension
  set(18, 7, 37, woodFence);
  set(18, 6, 37, "minecraft:iron_bars");
  // Cargo in Sampan 3
  set(17, 5, 31, "minecraft:barrel[facing=up]");
  set(19, 5, 31, "minecraft:barrel[facing=up]");
  set(18, 5, 33, "minecraft:lantern[hanging=false]");

  // North Dugout Canoe (X: 10..13, Z: 2..7)
  for (let z = 2; z <= 7; z++) {
    set(11, 4, z, log(woodStripped, "z"));
    set(12, 4, z, log(woodStripped, "z"));
  }
  for (let z = 3; z <= 6; z++) {
    set(10, 5, z, stair(woodStairs, "east"));
    set(13, 5, z, stair(woodStairs, "west"));
  }
  set(11, 5, 2, slab(woodSlab, "top"));
  set(12, 5, 2, slab(woodSlab, "top"));
  set(11, 5, 7, slab(woodSlab, "top"));
  set(12, 5, 7, slab(woodSlab, "top"));
  set(11, 5, 4, "minecraft:barrel[facing=up]");
  set(12, 5, 5, "minecraft:lantern[hanging=false]");
  // Mooring tie to North Jetty
  set(14, 5, 4, woodFence);
  set(15, 5, 4, woodFence);
  set(16, 5, 4, woodFence);

  // ==========================================
  // 4. FLOATING PRODUCE STALLS & VENDORS
  // ==========================================

  // NW Produce Raft Canopies & Stalls (X: 4..12, Z: 5..14)
  const nwPosts = [[5, 6], [11, 6], [5, 9], [11, 9], [5, 13], [11, 13]];
  for (const [px, pz] of nwPosts) {
    for (let y = 6; y <= 8; y++) {
      set(px, y, pz, woodFence);
    }
  }
  // Stall 1 Canopy (Fruit): Yellow and Lime Wool (Y = 8)
  for (let x = 5; x <= 11; x++) {
    for (let z = 6; z <= 9; z++) {
      const wool = ((x + z) % 2 === 0) ? "minecraft:yellow_wool" : "minecraft:lime_wool";
      set(x, 8, z, wool);
    }
  }
  // Stall 2 Canopy (Grains & Dry Goods): Orange Wool (Y = 8)
  for (let x = 5; x <= 11; x++) {
    for (let z = 10; z <= 13; z++) {
      const wool = ((x + z) % 2 === 0) ? "minecraft:orange_wool" : "minecraft:white_wool";
      set(x, 8, z, wool);
    }
  }
  // Produce Goods on NW Raft
  set(6, 6, 7, "minecraft:melon");
  set(7, 6, 7, "minecraft:melon");
  set(8, 6, 7, "minecraft:carved_pumpkin[facing=south]");
  set(9, 6, 7, "minecraft:pumpkin");
  set(10, 6, 7, "minecraft:melon");
  set(6, 6, 11, "minecraft:hay_block[axis=y]");
  set(7, 6, 11, "minecraft:hay_block[axis=y]");
  set(8, 6, 11, "minecraft:barrel[facing=up]");
  set(9, 6, 11, "minecraft:barrel[facing=up]");
  set(10, 6, 11, "minecraft:hay_block[axis=y]");
  set(5, 9, 6, "minecraft:lantern[hanging=false]");
  set(11, 9, 6, "minecraft:lantern[hanging=false]");
  set(5, 9, 13, "minecraft:lantern[hanging=false]");
  set(11, 9, 13, "minecraft:lantern[hanging=false]");

  // NE Tea & Spice House Shelter (X: 26..34, Z: 5..14)
  const nePosts = [[27, 6], [33, 6], [27, 13], [33, 13]];
  for (const [px, pz] of nePosts) {
    for (let y = 6; y <= 9; y++) {
      set(px, y, pz, log(woodLog, "y"));
    }
  }
  // Low tea counter railings
  for (let x = 28; x <= 32; x++) {
    set(x, 6, 6, woodFence);
    set(x, 6, 13, woodFence);
  }
  for (let z = 7; z <= 12; z++) {
    set(33, 6, z, woodFence);
  }
  // Tea House Hipped Thatch Roof (Y = 9..11)
  for (let x = 26; x <= 34; x++) {
    set(x, 9, 5, stair(roofStairs, "north"));
    set(x, 9, 14, stair(roofStairs, "south"));
  }
  for (let z = 5; z <= 14; z++) {
    set(26, 9, z, stair(roofStairs, "west"));
    set(34, 9, z, stair(roofStairs, "east"));
  }
  for (let x = 27; x <= 33; x++) {
    set(x, 10, 6, stair(roofStairs, "north"));
    set(x, 10, 13, stair(roofStairs, "south"));
  }
  for (let z = 6; z <= 13; z++) {
    set(27, 10, z, stair(roofStairs, "west"));
    set(33, 10, z, stair(roofStairs, "east"));
  }
  for (let x = 28; x <= 32; x++) {
    for (let z = 7; z <= 12; z++) {
      set(x, 11, z, slab(roofSlab, "bottom"));
    }
  }
  // Hanging lanterns under tea house eaves
  set(28, 9, 7, "minecraft:lantern[hanging=true]");
  set(32, 9, 7, "minecraft:lantern[hanging=true]");
  set(28, 9, 12, "minecraft:lantern[hanging=true]");
  set(32, 9, 12, "minecraft:lantern[hanging=true]");

  // SW Artisan Craft Stall (X: 4..12, Z: 26..35)
  const swPosts = [[5, 28], [11, 28], [5, 33], [11, 33]];
  for (const [px, pz] of swPosts) {
    for (let y = 6; y <= 8; y++) {
      set(px, y, pz, woodFence);
    }
  }
  // Craft Awning (Red & Cyan Wool)
  for (let x = 5; x <= 11; x++) {
    for (let z = 28; z <= 33; z++) {
      const wool = ((x + z) % 2 === 0) ? "minecraft:red_wool" : "minecraft:cyan_wool";
      set(x, 8, z, wool);
    }
  }
  // Craft Goods: Pots, Terracotta, Barrels
  set(6, 6, 29, "minecraft:orange_terracotta");
  set(7, 6, 29, "minecraft:terracotta");
  set(8, 6, 29, "minecraft:barrel[facing=up]");
  set(9, 6, 29, "minecraft:terracotta");
  set(10, 6, 29, "minecraft:orange_terracotta");
  set(6, 6, 32, "minecraft:barrel[facing=up]");
  set(10, 6, 32, "minecraft:barrel[facing=up]");
  set(5, 9, 28, "minecraft:lantern[hanging=false]");
  set(11, 9, 28, "minecraft:lantern[hanging=false]");

  // SE Fisher's Shed & Drying Racks (X: 25..35, Z: 26..35)
  const sePosts = [[27, 28], [33, 28], [27, 33], [33, 33]];
  for (const [px, pz] of sePosts) {
    for (let y = 6; y <= 8; y++) {
      set(px, y, pz, log(woodLog, "y"));
    }
  }
  // Shed Roof (Y = 8)
  for (let x = 26; x <= 34; x++) {
    for (let z = 27; z <= 34; z++) {
      set(x, 8, z, slab(roofSlab, "bottom"));
    }
  }
  // Fish drying racks (fences and chains)
  set(26, 6, 26, woodFence);
  set(26, 7, 26, woodFence);
  set(27, 7, 26, "minecraft:chain[axis=x]");
  set(28, 7, 26, "minecraft:chain[axis=x]");
  set(29, 7, 26, woodFence);
  set(29, 6, 26, woodFence);
  // Barrels and tackle
  set(28, 6, 29, "minecraft:barrel[facing=up]");
  set(29, 6, 29, "minecraft:barrel[facing=up]");
  set(32, 6, 29, "minecraft:barrel[facing=up]");
  set(28, 6, 32, "minecraft:barrel[facing=up]");
  set(32, 6, 32, "minecraft:barrel[facing=up]");
  set(27, 9, 28, "minecraft:lantern[hanging=false]");
  set(33, 9, 28, "minecraft:lantern[hanging=false]");

  // ==========================================
  // 5. RAILINGS, POSTS & BEACONS
  // ==========================================

  // North Landing Jetty Mooring Posts & Lanterns
  for (const z of [0, 3, 6, 9]) {
    set(17, 6, z, log(woodStripped, "y"));
    set(21, 6, z, log(woodStripped, "y"));
  }
  // Fences along jetty edges
  for (let z = 1; z <= 8; z++) {
    if (z % 3 !== 0) {
      set(17, 6, z, woodFence);
      set(21, 6, z, woodFence);
    }
  }
  // Entrance Beacon Lanterns at the north landing tip (Z = 0)
  set(17, 7, 0, "minecraft:lantern[hanging=false]");
  set(21, 7, 0, "minecraft:lantern[hanging=false]");

  // Mooring Bollards around Central Plaza corners
  const bollards = [
    [12, 10], [26, 10], [12, 26], [26, 26],
    [17, 30], [21, 30]
  ];
  for (const [bx, bz] of bollards) {
    set(bx, 6, bz, log(woodStripped, "y"));
    set(bx, 7, bz, woodFence);
    set(bx, 8, bz, "minecraft:lantern[hanging=false]");
  }

  // ==========================================
  // 6. TERRAIN CONFORMATION (RULE 6)
  // ==========================================
  // Scan all occupied columns and sink structural stilts/pilings down to seabed

  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      let minY = -1;
      let maxY = -1;
      for (let y = 0; y < H; y++) {
        if (world[x][y][z] !== null) {
          if (minY === -1) minY = y;
          maxY = y;
        }
      }

      if (minY !== -1) {
        // Compute node-local ground height from terrain query
        const localTerrainH = Math.round(api.heightAt(x, z));
        const groundY = Math.max(0, Math.min(H - 1, seatY + localTerrainH));

        if (groundY < minY) {
          // Terrain falls away into water: build stilts down to riverbed
          const isPillar = (
            (x === 13 || x === 19 || x === 25 || x === 17 || x === 21) ||
            (z === 12 || z === 18 || z === 24 || z === 10 || z === 26) ||
            (x % 4 === 0 && z % 4 === 0)
          );
          const stiltBlock = isPillar ? log(woodLog, "y") : log(woodStripped, "y");

          for (let y = groundY + 1; y < minY; y++) {
            set(x, y, z, stiltBlock);
          }
          // Firm stone plinth footing on the riverbed / seabed
          set(x, groundY, z, groundPlinth);
        } else if (groundY > minY) {
          // Terrain rises up into hill/ridge: step plinth up to meet ground
          for (let y = minY; y <= groundY; y++) {
            if (world[x][y][z] === null || y < seatY) {
              set(x, y, z, groundPlinth);
            }
          }
        }
      }
    }
  }

  // Submerged horizontal cross-bracing ties at Y = 2 and Y = 3
  for (let x = 2; x <= 35; x += 4) {
    for (let z = 2; z <= 35; z++) {
      if (get(x, 2, z) !== null && get(x, 2, z) !== groundPlinth) {
        if (get(x, 2, z - 1) === null && get(x, 4, z) !== null) {
          set(x, 2, z, log(woodStripped, "z"));
        }
      }
    }
  }

  // ==========================================
  // 7. EMIT TO API (DETERMINISTIC FLUSH)
  // ==========================================
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = world[x][y][z];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "Floating Market Bazaar",
    seatY: 5,
    anchors: {
      front: [19, 5, 0],
      pier: [19, 5, 0],
      hall: [19, 5, 18],
      market: [19, 5, 18],
      dock_west: [4, 5, 22],
      dock_east: [33, 5, 22]
    },
    interiors: [
      {
        min: [14, 6, 13],
        max: [24, 9, 23],
        kind: "hall"
      },
      {
        min: [28, 6, 7],
        max: [32, 8, 12],
        kind: "quarters"
      }
    ]
  };
}
